import sys
from xml.dom import minidom

doc = minidom.parse("unpacked/word/document.xml")
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def q(tag):
    return f"{{{W}}}{tag}"

def text_of(p):
    parts = []
    for t in p.getElementsByTagName(q("t")):
        if t.firstChild:
            parts.append(t.data if t.firstChild.nodeType == t.TEXT_NODE else "")
    return "".join(parts)

for i, p in enumerate(doc.getElementsByTagName(q("p"))):
    pPr = p.getElementsByTagName(q("pPr"))
    style = ""
    if pPr:
        pStyle = pPr[0].getElementsByTagName(q("pStyle"))
        if pStyle:
            style = pStyle[0].getAttribute(q("val"))
    txt = text_of(p).strip()
    marker = " <== HEADLINE" if style.startswith("Heading") or style in ("Title", "Subtitle") else ""
    print(f"[{i}] style={style!r} text={txt[:80]!r}{marker}")

